Matrix4x4Flagged nsIFrame::GetTransformMatrix(
    ViewportType aViewportType, RelativeTo aStopAtAncestor,
    nsIFrame** aOutAncestor, TransformMatrixFlags aFlags) const {
  MOZ_ASSERT(aOutAncestor, "Need a place to put the ancestor!");

  auto GetPositionMaybeIgnoringScrolling = [aFlags](const nsIFrame* aFrame) {
    return aFlags.contains(TransformMatrixFlag::IgnoreScrolling)
               ? aFrame->GetPositionIgnoringScrollingAndSticky()
               : aFrame->GetPosition();
  };

  /* If we're transformed, we want to hand back the combination
   * transform/translate matrix that will apply our current transform, then
   * shift us to our parent.
   */
  const bool isTransformed = IsTransformed();
  const nsIFrame* zoomedContentRoot = nullptr;
  if (aStopAtAncestor.mViewportType == ViewportType::Visual) {
    zoomedContentRoot = ViewportUtils::IsZoomedContentRoot(this);
    if (zoomedContentRoot) {
      MOZ_ASSERT(aViewportType != ViewportType::Visual);
    }
  }

  if (isTransformed || zoomedContentRoot) {
    MOZ_ASSERT(GetParent());
    Matrix4x4Flagged result;
    int32_t scaleFactor = aFlags.contains(TransformMatrixFlag::InCSSUnits)
                              ? AppUnitsPerCSSPixel()
                              : PresContext()->AppUnitsPerDevPixel();

    /* Compute the delta to the parent, which we need because we are converting
     * coordinates to our parent.
     */
    if (isTransformed) {
      // Note: this converts from Matrix4x4 to Matrix4x4Flagged.
      result = nsDisplayTransform::GetResultingTransformMatrix(
          this, nsPoint(), scaleFactor,
          nsDisplayTransform::INCLUDE_PERSPECTIVE);
    }

    // The offset from a zoomed content root to its parent (e.g. from
    // a canvas frame to a scroll frame) is in layout coordinates, so
    // apply it before applying any layout-to-visual transform.
    *aOutAncestor = GetParent();
    nsPoint delta = GetPositionMaybeIgnoringScrolling(this);
    /* Combine the raw transform with a translation to our parent. */
    result.PostTranslate(NSAppUnitsToFloatPixels(delta.x, scaleFactor),
                         NSAppUnitsToFloatPixels(delta.y, scaleFactor), 0.0f);

    if (zoomedContentRoot) {
      Matrix4x4Flagged layoutToVisual;
      if (aFlags.contains(TransformMatrixFlag::InCSSUnits)) {
        layoutToVisual = ViewportUtils::GetVisualToLayoutTransform(
                             zoomedContentRoot->GetContent())
                             .Inverse()
                             .ToUnknownMatrix();
      } else {
        layoutToVisual =
            ViewportUtils::GetVisualToLayoutTransform<LayoutDevicePixel>(
                zoomedContentRoot->GetContent())
                .Inverse()
                .ToUnknownMatrix();
      }
      result = result * layoutToVisual;
    }

    return result;
  }

  // We are not transformed, so the returned transform is just going to be a
  // translation up to whatever ancestor we decide to stop at.

  nsPoint crossdocOffset;
  *aOutAncestor =
      nsLayoutUtils::GetCrossDocParentFrameInProcess(this, &crossdocOffset);

  /* Otherwise, we're not transformed.  In that case, we'll walk up the frame
   * tree until we either hit the root frame or something that may be
   * transformed.  We'll then change coordinates into that frame, since we're
   * guaranteed that nothing in-between can be transformed.  First, however,
   * we have to check to see if we have a parent.  If not, we'll set the
   * outparam to null (indicating that there's nothing left) and will hand back
   * the identity matrix.
   */
  if (!*aOutAncestor) {
    return Matrix4x4Flagged();
  }

  /* Keep iterating while the frame can't possibly be transformed. */
  const nsIFrame* current = this;
  auto shouldStopAt = [](const nsIFrame* aCurrent, RelativeTo& aStopAtAncestor,
                         nsIFrame* aOutAncestor, TransformMatrixFlags aFlags) {
    return aOutAncestor->IsTransformed() ||
           ((aStopAtAncestor.mViewportType == ViewportType::Visual) &&
            ViewportUtils::IsZoomedContentRoot(aOutAncestor)) ||
           (aFlags.contains(
                TransformMatrixFlag::StopAtStackingContextAndDisplayPort) &&
            (aOutAncestor->IsStackingContext() ||
             DisplayPortUtils::FrameHasDisplayPort(aOutAncestor, aCurrent)));
  };

  // We run the GetOffsetToCrossDoc code here as an optimization, instead of
  // walking the parent chain here and then asking GetOffsetToCrossDoc to walk
  // the same parent chain and compute the offset.
  const int32_t finalAPD = PresContext()->AppUnitsPerDevPixel();
  // offset accumulates the offset at finalAPD.
  nsPoint offset = GetPositionMaybeIgnoringScrolling(this);

  int32_t currAPD = (*aOutAncestor)->PresContext()->AppUnitsPerDevPixel();
  // docOffset accumulates the current offset at currAPD, and then flushes to
  // offset at finalAPD when the APD changes or we finish.
  nsPoint docOffset = crossdocOffset;
  MOZ_ASSERT(crossdocOffset == nsPoint(0, 0) || !GetParent());

  while (*aOutAncestor != aStopAtAncestor.mFrame &&
         !shouldStopAt(current, aStopAtAncestor, *aOutAncestor, aFlags)) {
    docOffset += GetPositionMaybeIgnoringScrolling(*aOutAncestor);

    nsIFrame* parent = (*aOutAncestor)->GetParent();
    if (!parent) {
      crossdocOffset.x = crossdocOffset.y = 0;
      parent = nsLayoutUtils::GetCrossDocParentFrameInProcess(*aOutAncestor,
                                                              &crossdocOffset);

      int32_t newAPD =
          parent ? parent->PresContext()->AppUnitsPerDevPixel() : currAPD;
      if (!parent || newAPD != currAPD) {
        // Convert docOffset to finalAPD and add it to offset.
        offset += docOffset.ScaleToOtherAppUnits(currAPD, finalAPD);
        docOffset.x = docOffset.y = 0;
      }
      currAPD = newAPD;
      docOffset += crossdocOffset;

      if (!parent) {
        break;
      }
    }

    current = *aOutAncestor;
    *aOutAncestor = parent;
  }
  offset += docOffset.ScaleToOtherAppUnits(currAPD, finalAPD);

  NS_ASSERTION(*aOutAncestor, "Somehow ended up with a null ancestor...?");

  int32_t scaleFactor = aFlags.contains(TransformMatrixFlag::InCSSUnits)
                            ? AppUnitsPerCSSPixel()
                            : PresContext()->AppUnitsPerDevPixel();
  return Matrix4x4Flagged::Translation2d(
      NSAppUnitsToFloatPixels(offset.x, scaleFactor),
      NSAppUnitsToFloatPixels(offset.y, scaleFactor));
}

bool nsIFrame::IsTransformed() const {
  if (!HasAnyStateBits(NS_FRAME_MAY_BE_TRANSFORMED)) {
    MOZ_ASSERT(!IsCSSTransformed());
    MOZ_ASSERT(!GetParentSVGTransforms());
    return false;
  }
  return IsCSSTransformed() || GetParentSVGTransforms();
}

bool nsIFrame::HasPerspective() const {
  if (!IsCSSTransformed()) {
    return false;
  }
  nsIFrame* parent = GetClosestFlattenedTreeAncestorPrimaryFrame();
  if (!parent) {
    return false;
  }
  return parent->ChildrenHavePerspective();
}

nsIFrame* nsLayoutUtils::GetCrossDocParentFrameInProcess(
    const nsIFrame* aFrame, nsPoint* aCrossDocOffset) {
  if (nsIFrame* p = aFrame->GetParent()) {
    return p;
  }
  auto* embedder = aFrame->PresShell()->GetInProcessEmbedderFrame();
  if (embedder && aCrossDocOffset) {
    *aCrossDocOffset += embedder->GetExtraOffset();
  }
  return embedder;
}

Matrix4x4Flagged nsLayoutUtils::GetTransformToAncestor(
    RelativeTo aFrame, RelativeTo aAncestor, TransformMatrixFlags aFlags,
    nsIFrame** aOutAncestor) {
  nsIFrame* parent;
  Matrix4x4Flagged ctm;
  // Make sure we don't get an invalid combination of source and destination
  // RelativeTo values.
  MOZ_ASSERT(!(aFrame.mViewportType == ViewportType::Visual &&
               aAncestor.mViewportType == ViewportType::Layout));
  if (aFrame == aAncestor) {
    return ctm;
  }
  ctm = aFrame.mFrame->GetTransformMatrix(aFrame.mViewportType, aAncestor,
                                          &parent, aFlags);
  if (!aFrame.mFrame->Combines3DTransformWithAncestors()) {
    ctm.ProjectTo2D();
  }
  while (parent && parent != aAncestor.mFrame &&
         (!aFlags.contains(
              TransformMatrixFlag::StopAtStackingContextAndDisplayPort) ||
          (!parent->IsStackingContext() &&
           !DisplayPortUtils::FrameHasDisplayPort(parent)))) {
    nsIFrame* cur = parent;
    ctm = ctm * cur->GetTransformMatrix(aFrame.mViewportType, aAncestor,
                                        &parent, aFlags);
    if (!cur->Combines3DTransformWithAncestors()) {
      ctm.ProjectTo2D();
    }
  }
  if (aOutAncestor) {
    *aOutAncestor = parent;
  }
  return ctm;
}

struct BoxToRect : public nsLayoutUtils::BoxCallback {
  const nsIFrame* mRelativeTo;
  RectCallback* mCallback;
  nsLayoutUtils::GetAllInFlowRectsFlags mFlags;
  // If the frame we're measuring relative to is the root, we know all frames
  // are descendants of it, so we don't need to compute the common ancestor
  // between a frame and mRelativeTo.
  bool mRelativeToIsRoot;
  // For the same reason, if the frame we're measuring relative to is the target
  // (this is useful for IntersectionObserver), we know all frames are
  // descendants of it except if we're in a continuation or ib-split-sibling of
  // it.
  bool mRelativeToIsTarget;

  BoxToRect(const nsIFrame* aTargetFrame, const nsIFrame* aRelativeTo,
            RectCallback* aCallback,
            nsLayoutUtils::GetAllInFlowRectsFlags aFlags)
      : mRelativeTo(aRelativeTo),
        mCallback(aCallback),
        mFlags(aFlags),
        mRelativeToIsRoot(!aRelativeTo->GetParent()),
        mRelativeToIsTarget(aRelativeTo == aTargetFrame) {}

  void AddBox(nsIFrame* aFrame) override {
    nsRect r;
    nsIFrame* outer = SVGUtils::GetOuterSVGFrameAndCoveredRegion(aFrame, &r);
    const bool usingSVGOuterFrame = !!outer;
    if (!outer) {
      outer = aFrame;
      if (mFlags.contains(
              nsLayoutUtils::GetAllInFlowRectsFlag::UseContentBox)) {
        r = aFrame->GetContentRectRelativeToSelf();
      } else if (mFlags.contains(
                     nsLayoutUtils::GetAllInFlowRectsFlag::UsePaddingBox)) {
        r = aFrame->GetPaddingRectRelativeToSelf();
      } else if (mFlags.contains(
                     nsLayoutUtils::GetAllInFlowRectsFlag::UseMarginBox)) {
        r = aFrame->GetMarginRectRelativeToSelf();
      } else if (mFlags.contains(nsLayoutUtils::GetAllInFlowRectsFlag::
                                     UseMarginBoxWithAutoResolvedAsZero)) {
        r = aFrame->GetRectRelativeToSelf();
        nsMargin usedMargin =
            aFrame->GetUsedMargin().ApplySkipSides(aFrame->GetSkipSides());
        const auto* styleMargin = aFrame->StyleMargin();
        const auto anchorResolutionParams =
            AnchorPosResolutionParams::From(aFrame);
        for (const Side side : AllPhysicalSides()) {
          if (styleMargin->GetMargin(side, anchorResolutionParams)->IsAuto()) {
            usedMargin.Side(side) = 0;
          }
        }
        r.Inflate(usedMargin);
      } else if (mFlags.contains(nsLayoutUtils::GetAllInFlowRectsFlag::
                                     UseInkOverflowAsBox)) {
        r = aFrame->InkOverflowRectRelativeToSelf();
      } else {
        // Use the border-box.
        r = aFrame->GetRectRelativeToSelf();
      }
    }
    if (outer != mRelativeTo) {
      if (mFlags.contains(
              nsLayoutUtils::GetAllInFlowRectsFlag::AccountForTransforms)) {
        const bool isAncestorKnown = [&] {
          if (mRelativeToIsRoot) {
            return true;
          }
          if (mRelativeToIsTarget && !mInTargetContinuation) {
            return !usingSVGOuterFrame;
          }
          return false;
        }();
        if (isAncestorKnown) {
          r = nsLayoutUtils::TransformFrameRectToAncestor(outer, r,
                                                          mRelativeTo);
        } else {
          nsLayoutUtils::TransformRect(outer, mRelativeTo, r);
        }
      } else {
        if (aFrame->PresContext() != mRelativeTo->PresContext()) {
          r += outer->GetOffsetToCrossDoc(mRelativeTo);
        } else {
          r += outer->GetOffsetTo(mRelativeTo);
        }
      }
    }
    mCallback->AddRect(r);
  }
}

static Maybe<nsRect> GetUntransformedRectToAncestor(
    const nsIFrame* aFrame, const nsRect& aRect, const nsIFrame* aAncestor) {
  if (!aAncestor || aRect.width < 0 || aRect.height < 0 ||
      aRect.width > nscoord_MAX || aRect.height > nscoord_MAX) {
    return Nothing();
  }
  CheckedInt<nscoord> x = aRect.x;
  CheckedInt<nscoord> y = aRect.y;
  for (const nsIFrame* frame = aFrame; frame != aAncestor;
       frame = frame->GetParent()) {
    if (!frame || frame->PresContext() != aAncestor->PresContext() ||
        frame->IsTransformed() || frame->IsInSVGTextSubtree() ||
        frame->HasAnyStateBits(NS_FRAME_SVG_LAYOUT)) {
      return Nothing();
    }
    x += frame->GetPosition().x;
    y += frame->GetPosition().y;
    if (!x.isValid() || !y.isValid()) {
      return Nothing();
    }
  }
  const auto right = x + aRect.width;
  const auto bottom = y + aRect.height;
  if (!right.isValid() || !bottom.isValid() || x.value() < nscoord_MIN ||
      y.value() < nscoord_MIN || right.value() > nscoord_MAX ||
      bottom.value() > nscoord_MAX) {
    return Nothing();
  }
  return Some(nsRect(x.value(), y.value(), aRect.width, aRect.height));
}

/* static */ void nsLayoutUtils::ConstrainToCoordValues(double& aStart,
                                                        double& aSize) {
  MOZ_ASSERT(std::isnan(aSize) || aSize >= 0);

  double max = aStart + aSize;

  // Clamp the end points to within nscoord range
  ::ConstrainToCoordValues(aStart);
  ::ConstrainToCoordValues(max);

  // Here we try to make sure that the resulting nsRect will continue to cover
  // as much of the area that was covered by the original gfx Rect as possible.

  // We must also clamp aSize to {0,nscoord_MAX} since nsRect::Width/Height()
  // can't return a value greater than nscoord_MAX. If aSize is greater than
  // nscoord_MAX then we reduce it to nscoord_MAX while keeping the rect
  // centered:

  aSize = max - aStart;
  // If the width if still greater than the max nscoord, then bring both
  // endpoints in by the same amount until it fits.
  if (MOZ_UNLIKELY(std::isnan(aSize))) {
    // Can happen if aStart is -inf and aSize is +inf for example.
    // If either aStart or aSize is NaN on entry to this function then the
    // calculations above this will make the other one NaN too, so this check
    // ensures that we do not return NaN for either value.
    aStart = 0.0f;
    aSize = nscoord_MAX;
  } else if (aSize > nscoord_MAX) {
    double excess = aSize - nscoord_MAX;
    excess /= 2;

    aStart += excess;
    aSize = nscoord_MAX;
  } else if (aSize < nscoord_MIN) {
    double excess = aSize - nscoord_MIN;
    excess /= 2;

    aStart -= excess;
    aSize = nscoord_MIN;
  }
}

template <typename T>
nsRect nsLayoutUtils::ScaleThenRoundGfxRectToAppRect(const T& aRect,
                                                     const float aFactor) {
  // Get a new Rect whose units are app units by scaling by the specified
  // factor.
  T scaledRect = aRect;
  scaledRect.Scale(aFactor);

  nsRect retval;

  double start = double(scaledRect.x);
  double size = double(scaledRect.width);
  // We now need to constrain our results to the max and min values for coords.
  ConstrainToCoordValues(start, size);
  // ConstrainToCoordValues ensures converting to nscoord is safe.
  retval.x = NSToCoordRoundWithClamp(start);
  retval.width = NSToCoordRoundWithClamp(size);

  start = double(scaledRect.y);
  size = double(scaledRect.height);
  ConstrainToCoordValues(start, size);
  retval.y = NSToCoordRoundWithClamp(start);
  retval.height = NSToCoordRoundWithClamp(size);

  if (!aRect.Width()) {
    retval.SetWidth(0);
  }

  if (!aRect.Height()) {
    retval.SetHeight(0);
  }

  return retval;
}

void DOMRect::SetLayoutRect(const nsRect& aLayoutRect) {
  double scale = 65536.0;
  // Round to the nearest 1/scale units. We choose scale so it can be
  // represented exactly by machine floating point.
  double scaleInv = 1 / scale;
  double t2pScaled = scale / AppUnitsPerCSSPixel();
  double x = RoundFloat(aLayoutRect.x * t2pScaled) * scaleInv;
  double y = RoundFloat(aLayoutRect.y * t2pScaled) * scaleInv;
  SetRect(x, y, RoundFloat(aLayoutRect.XMost() * t2pScaled) * scaleInv - x,
          RoundFloat(aLayoutRect.YMost() * t2pScaled) * scaleInv - y);
}

void DOMRect::SetLayoutRect(const nsRect& aLayoutRect) {
  double scale = 65536.0;
  // Round to the nearest 1/scale units. We choose scale so it can be
  // represented exactly by machine floating point.
  double scaleInv = 1 / scale;
  double t2pScaled = scale / AppUnitsPerCSSPixel();
  double x = RoundFloat(aLayoutRect.x * t2pScaled) * scaleInv;
  double y = RoundFloat(aLayoutRect.y * t2pScaled) * scaleInv;
  SetX(x);
  SetY(y);
  SetWidth(RoundFloat(aLayoutRect.XMost() * t2pScaled) * scaleInv - x);
  SetHeight(RoundFloat(aLayoutRect.YMost() * t2pScaled) * scaleInv - y);
}
